ach?></select></label><label>Thứ tự <input type="number" name="sort_order" min="0" max="1000000" value="<?=e($i['sort_order'])?>"></label><button>Lưu ảnh</button></form></td></tr><?php endforeach?></table></div><?php echo '</section>';?>